(* CAS_CONTRACT statement: Independently determine whether the exact B3-v2/W7 design is algebraically coherent under the frozen conventions. A candidate target below is a falsifiable claim, not an allowed intermediate assumption. Any normalization, branch, graph, or convention mismatch is a fail or inconclusive result, never silently repaired. *)
ClearAll[dotD]; dotD[a_,b_]:=a[[1]]b[[1]]-a[[2]]b[[2]]-a[[3]]b[[3]]-a[[4]]b[[4]];
(* Direct u/v row-ii spin sums in eta_D=diag(+---). *)
s1={{0,1},{1,0}}; s2={{0,-I},{I,0}}; s3={{1,0},{0,-1}}; z=ConstantArray[0,{2,2}]; id=IdentityMatrix[2]; g0=ArrayFlatten[{{id,z},{z,-id}}]; gs=Table[ArrayFlatten[{{z,sg},{-sg,z}}],{sg,{s1,s2,s3}}]; gu=Prepend[gs,g0]; sig={1,-1,-1,-1}; gd=MapThread[#1 #2&,{sig,gu}]; g5=I gu[[1]].gu[[2]].gu[[3]].gu[[4]]; pl=(IdentityMatrix[4]-g5)/2; vu=Table[gu[[m]].pl,{m,4}]; vd=Table[gd[[m]].pl,{m,4}]; sl[p_]:=p[[1]]gu[[1]]-p[[2]]gu[[2]]-p[[3]]gu[[3]]-p[[4]]gu[[4]]; p1=Array[a,4]; p2=Array[b,4]; p3=Array[c,4]; p4=Array[d,4]; tt=Sum[Tr[sl[p3].vu[[m]].sl[p1].vu[[n]]]Tr[sl[p2].vd[[m]].sl[p4].vd[[n]]],{m,4},{n,4}]; ss=Sum[Tr[sl[p2].vu[[m]].sl[p1].vu[[n]]]Tr[sl[p3].vd[[m]].sl[p4].vd[[n]]],{m,4},{n,4}]; xx=2Sum[Tr[sl[p3].vu[[m]].sl[p1].vu[[n]].sl[p2].vd[[m]].sl[p4].vd[[n]]],{m,4},{n,4}]; Print[InputForm[Expand[{tt-16dotD[p1,p4]dotD[p2,p3],ss-16dotD[p1,p4]dotD[p2,p3],xx+32dotD[p1,p4]dotD[p2,p3]}]]];
(* Invariant-measure normalization and MB reduction. *)
p2ang=(2Pi)/(2(2Pi)^3); phi2=(2Pi)/(32Pi^2); pref=FullSimplify[(1/(2e1))p2ang phi2]; ksint=Integrate[y2^3 Exp[-y2],{y2,0,Infinity}]Integrate[(1-mu)^2,{mu,-1,1}]Integrate[1,{zs,-1,1}]; Print[InputForm[{p2ang,phi2,pref,ksint,c0 ksint/(256Pi^3),c0 ksint/(3 256Pi^3)}]];
(* Exact six-species reaction stoichiometry. First 33 elastic columns are zero; columns 34..39 are three pair conversions and three e+e- pair rows. *)
flav={{1,2},{3,4},{5,6}}; un[k_]:=UnitVector[6,k]; pair[k_]:=un[flav[[k,1]]]+un[flav[[k,2]]]; conv={-pair[1]+pair[2],-pair[1]+pair[3],-pair[2]+pair[3]}; ann={-pair[1],-pair[2],-pair[3]}; S=Transpose[Join[Table[ConstantArray[0,6],{33}],conv,ann]]; left=NullSpace[Transpose[S]]; right=NullSpace[S]; rc=Join[Table[UnitVector[39,k],{k,33}],{UnitVector[39,34]-UnitVector[39,37]+UnitVector[39,38],UnitVector[39,35]-UnitVector[39,37]+UnitVector[39,39],UnitVector[39,36]-UnitVector[39,38]+UnitVector[39,39]}]; Print[InputForm[{MatrixRank[S],left,Length[right],Length[rc],MatrixRank[rc],Union[S.#&/@rc]}]];
(* Entropy exact vector and positive secant representation. *)
f={1/5,2/5,3/5,4/5}; ff=f[[1]]f[[2]](1-f[[3]])(1-f[[4]]); rr=f[[3]]f[[4]](1-f[[1]])(1-f[[2]]); Print[InputForm[{ff,rr,Log[ff/rr],ff-rr,FullSimplify[(ff-rr)Log[ff/rr]]}]]; Clear[F,R,t]; sec=Assuming[F>0&&R>0,FullSimplify[Integrate[1/(R+t(F-R)),{t,0,1}]]]; Print[InputForm[{sec,Assuming[F>0&&R>0,FullSimplify[(F-R)^2 sec-(F-R)(Log[F]-Log[R])]]}]];
(* Finite-me shell root and exact rational test vectors. *)
Clear[P0,Px,Py,Pz,nx,ny,nz,m4]; gp[a_,b_]:=-a[[1]]b[[1]]+a[[2]]b[[2]]+a[[3]]b[[3]]+a[[4]]b[[4]]; P={P0,Px,Py,Pz}; n4={1,nx,ny,nz}; sv=-gp[P,P]; den=2(P0-Px nx-Py ny-Pz nz); ee=(sv-m4^2)/den; k3=ee n4; k4=P-k3; Print[InputForm[{ee,Factor[gp[k3,k3]],Factor[gp[k4,k4]+m4^2],FullSimplify[(gp[k4,k4]+m4^2)/.nz^2->1-nx^2-ny^2]}]];
